package org.eclipse.rdf4j.tools.serverboot;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.resttestclient.TestRestTemplate;
import org.springframework.boot.resttestclient.autoconfigure.AutoConfigureTestRestTemplate;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseEntity;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.context.ContextConfiguration;

@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
@ContextConfiguration(initializers = Rdf4jServerWorkbenchApplicationTest.IsolatedAppDataInitializer.class)
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
		"server.servlet.session.cookie.same-site=strict", "server.servlet.session.cookie.secure=true",
		"server.servlet.session.cookie.path=/rdf4j-workbench", "server.servlet.session.cookie.http-only=true" })
@AutoConfigureTestRestTemplate
class WorkbenchSessionCookiePolicyTest {

	@LocalServerPort
	private int port;

	@Autowired
	private TestRestTemplate restTemplate;

	@Test
	void explicitlyConfiguredCookiePolicyAndFlagsArePreserved() {
		ResponseEntity<String> response = restTemplate.getForEntity(
				"http://localhost:" + port + "/rdf4j-workbench/repositories", String.class);
		assertThat(response.getStatusCode().is2xxSuccessful()).isTrue();
		assertThat(response.getHeaders().get(HttpHeaders.SET_COOKIE)).isNotNull()
				.anySatisfy(cookie -> assertThat(cookie).startsWith("JSESSIONID=")
						.contains("SameSite=Strict", "Secure", "HttpOnly", "Path=/rdf4j-workbench"));
	}
}
